% Go to working directory of model
openExample("simulink_automotive/ModelingAnAntiLockBrakingSystemExample");

% Load model
load_system("sldemo_absbrake");

% Simulate model
sim("sldemo_absbrake");

% Open the Simulation Data Inspector
Simulink.sdi.view;

entry.translation:
