entry.text:
% Generate timeseries data
time = linspace(0,20,100);

sine_vals = sin(2*pi/5*time);
sine_ts = timeseries(sine_vals,time);
sine_ts.Name = "Sine, T=5";

% Create a Simulation Data Inspector run
sineRun = Simulink.sdi.Run.create;
sineRun.Name = "Sine Wave";
sineRun.Description = "T=5";

% Add timeseries data to run
add(sineRun,"vars",sine_ts);

% Get signal object and plot signal
sine_sig = getSignalByIndex(sineRun, 1);
plotOnSubPlot(sine_sig,1,1,true);

% View the signal in the Simulation Data Inspector
Simulink.sdi.view;

