entry.text:
% Go to working directory of model
openExample("simulink_automotive/ModelingAnAntiLockBrakingSystemExample");

% Load model
load_system("sldemo_absbrake");

% Simulate model
sim("sldemo_absbrake");

% Access the most recent run in the Simulation Data Inspector
run = Simulink.sdi.Run.getLatest;

% Get signal IDs from run object
sig1 = getSignalIDByIndex(run,1);
sig2 = getSignalIDByIndex(run,2);

% Compare signals
diff = Simulink.sdi.compareSignals(sig1,sig2);

% Check if signals are within tolerance
match = diff.Status

