entry.text:
% Go to working directory of model
openExample("simulink_automotive/ModelingAnAntiLockBrakingSystemExample");

% Load model
load_system("sldemo_absbrake");

% Set the desired slip ratio to 0.24 and simulate
set_param("sldemo_absbrake/Desired relative slip","Value","0.24");
sim("sldemo_absbrake");

% Change the desired slip ratio to 0.25 and simulate
set_param("sldemo_absbrake/Desired relative slip","Value","0.25");
sim("sldemo_absbrake");

% Compare runs
runID1 = Simulink.sdi.getRunIDByIndex(1);
runID2 = Simulink.sdi.getRunIDByIndex(2);
diffResult = Simulink.sdi.compareRuns(runID1,runID2);

% Get summary of the comparison result
match = diffResult.Summary

