entry.text:
% Go to working directory of model
openExample("simulink_aerospace/AircraftLongitudinalFlightControlExample");

% Open the Simulation Data Inspector to view data during simulation
Simulink.sdi.view

% Ensure PCT support is enabled
Simulink.sdi.enablePCTSupport("local");

% Define Ts values
Ts_vals = [0.01,0.02,0.05,0.1,0.2,0.5,1];

parfor index = 1:7
 % Select value for Ts
 Ts_val = Ts_vals(index);

 % Load system and select signals to log
 load_system("slexAircraftExample");
 Simulink.sdi.markSignalForStreaming("slexAircraftExample/Pilot",1,"on");
 Simulink.sdi.markSignalForStreaming("slexAircraftExample/Aircraft Dynamics Model",4,"on");

 % Change the filter time constant and simulate
 modelWorkspace = get_param("slexAircraftExample","modelworkspace");
 assignin(modelWorkspace,"Ts",Ts_val);
 sim("slexAircraftExample");
end

entry.translation:
